from workflow import dispatch
def run(quantity):
    return dispatch.execute(quantity)


def stable(value):
    return value + 10

def build_request(quantity):
    """Adapt a nonnegative integer quantity for the quote tool."""
    return {"quantity": str(quantity)}

from . import codec, service

def execute(quantity):
    return service.quote(**codec.build_request(quantity))

def quote(quantity):
    if type(quantity) is not int or quantity < 0:
        raise TypeError('quantity must be a nonnegative integer')
    return quantity * RATE

